  ui_story_30780101_71_dialog_content = "Pero... No puedo encontrar ese Eclipsite, así que no puedo dárselo como regalo...",
  ui_story_30780101_72_dialog_content = "Bueno, aparte de ese Eclipsite, ¿hay algo más que le guste?",
  ui_story_30780101_73_dialog_content = "¿Algo más? Entonces tiene que ser <color=#FFB400>yo</color>.",
