  ui_story_30780101_79_dialog_content = "Entiendo que ustedes dos no quieren separarse, pero ¿no la asustará si hacen eso?",
  ui_story_30780101_80_dialog_content = "Bueno... Entonces, ¿qué debo hacer?",
