  ui_story_30780101_88_dialog_content = "La banda elástica se puede usar para atar a Dayna y a mí juntos.",
  ui_story_30780101_89_dialog_content = "Si de alguna manera me alejo demasiado de Dayna, la banda elástica me llevará de vuelta a ella.",
