  ui_story_30780101_98_dialog_content = "Si es una bomba de tiempo, Dayna y yo tendremos que cortar los cables rojo y azul al mismo tiempo para desactivarla.",
  ui_story_30780101_99_dialog_content = "Si es una bomba de tiempo con los cables rojo y azul conectados, Dayna y yo tendremos que cortar ambos cables al mismo tiempo para desactivarla.",
  ui_story_30780101_100_dialog_content = "Eso definitivamente facilitará nuestra cooperación.",
  ui_story_30780101_101_dialog_content = "(Dios mío... No entiendo la forma en que ella piensa...)",
  ui_story_30780101_102_dialog_content = "(Iba a sugerir algún tipo de juego de mesa para jugar juntos...)",
  ui_story_30780101_103_dialog_content = "PlayerName, ¿qué opinas de esto como un regalo?",
  ui_story_30780101_104_dialog_content = "No creo que este sea un regalo apropiado...",
  ui_story_30780101_105_dialog_content = "¿En serio? Sabía que yo...",
  ui_story_30780101_106_dialog_content = "N-no estés triste... V-veamos si podemos intentar algo más.",
  ui_story_30780101_107_dialog_content = "No pensemos en lo que a Dayna le gusta... Démosle <color=#FFB400>algo que necesita</color>.",
  ui_story_30780101_108_dialog_content = "Por ejemplo, parece que le gusta usar trajes limpios. ¿Por qué no le damos un cepillo de cerdas suaves para cuidar sus trajes?",
  ui_story_30780101_109_dialog_content = "¿Mmm? Suena como algo que Dayna necesitaría...",
  ui_story_30780101_110_dialog_content = "Pero ella ya tiene un juego completo de herramientas para cuidar sus trajes. No creo que necesite más cepillos.",
  ui_story_30780101_111_dialog_content = "Déjame pensar... Algo más que Dayna necesita...",
  ui_story_30780101_112_dialog_content = "¡Entendido! Ella necesita un <color=#FFB400>botiquín médico portátil</color>!",
  ui_story_30780101_113_dialog_content = "¿Botiquín?",
  ui_story_30780101_114_dialog_content = "Así es. A veces Dayna iba a misiones sin mí.",
  ui_story_30780101_115_dialog_content = "Siempre estaba herida cuando regresaba, y los trajes que le gustaban estarían en un desastre feo.",
  ui_story_30780101_116_dialog_content = "No sé por qué hace eso, pero siempre me preocupa...",
  ui_story_30780101_117_dialog_content = "Si le doy un botiquín médico portátil, se encargará de ella por mí cuando vuelva a ir sola en misiones.",
  ui_story_30780101_118_dialog_content = "Después de todo, hemos acordado trabajar juntos para encontrar al Eclipsite que mató a nuestros padres.",
  ui_story_30780101_119_dialog_content = "Si lleva un botiquín médico portátil, al menos podrá evitar que sus heridas manchen su traje antes de encontrarse con el Eclipsito...",
  ui_story_30780101_120_dialog_content = "Suena realmente bien... Comparado con lo que acabas de sugerir, Robyn, esta idea es tan buena que apenas puedo creer que sea tuya...",
  ui_story_30780101_121_dialog_content = "Consíguela uno entonces.",
  ui_story_30780101_122_dialog_content = "Gracias, PlayerName. Sin ti, nunca podría haber pensado en un regalo tan adecuado para ella.",
  ui_story_30780101_123_dialog_content = "Debería <color=#FFB400>darte un regalo también</color> para devolverte el favor.",
  ui_story_30780101_124_dialog_content = "<size=45>¡¿?!</size>",
  ui_story_30780101_125_dialog_content = "<size=45>N-no, no, no...!!</size>",
  ui_story_30780601_1_dialog_content = "(Uf, este debería ser el último trabajo...)",
  ui_story_30780601_2_dialog_content = "(¿Este debería ser el lugar, verdad?)",
  ui_story_30780601_3_dialog_content = "<color=#e8d9bb>Ding—Dong—</color>",
  ui_story_30780601_4_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_30780601_5_dialog_content = "Hola, por favor retrocede y mantén una distancia segura de mí. De lo contrario, las consecuencias serán graves...",
  ui_story_30780601_6_dialog_content = "¡E-está bien!",
  ui_story_30780601_7_dialog_content = "Ah... Eres tú, PlayerName...",
  ui_story_30780601_8_dialog_content = "Lamento eso, pensé que eras un vendedor o alguna otra persona molesta que va de puerta en puerta... Ya puedes relajarte.",
  ui_story_30780601_9_dialog_content = "Eh, está bien...",
  ui_story_30780601_10_dialog_content = "Traje los libros que solicitaste, Robyn.",
  ui_story_30780601_11_dialog_content = "Si no hay nada más, debería irme—",
  ui_story_30780601_12_dialog_content = "...",
  ui_story_30780601_13_dialog_content = "¿Qué pasa?",
  ui_story_30780601_14_dialog_content = "Todavía queda una última parte de mi solicitud...",
  ui_story_30780601_15_dialog_content = "¿Eh? ¿Olvidé algo?",
  ui_story_30780601_16_dialog_content = "Hmm... Necesito que me des un breve resumen de cada uno de estos libros, PlayerName.",
  ui_story_30780601_17_dialog_content = "Intenté que Dayna leyera libros conmigo...",
  ui_story_30780601_18_dialog_content = "Pero ella nunca se calmó lo suficiente como para leer algo.",
  ui_story_30780601_19_dialog_content = "Además, la mayoría de estos libros son sobre lugares de todo el mundo.",
  ui_story_30780601_20_dialog_content = "Así que pensé que un viajero como tú podría ser capaz de ayudar. ¿Estaría bien, PlayerName?",
  ui_story_30780601_21_dialog_content = "Ya veo. Eso no debería ser un problema. Después de todo, ya terminé con el trabajo del día.",
  ui_story_30780601_22_dialog_content = "Entonces... Pasa adelante.",
  ui_story_30780601_23_dialog_content = "¿Eh? ¿Me estás dejando entrar directamente a tu casa?",
  ui_story_30780601_24_dialog_content = "Sí... Ya he ordenado todo. Estoy seguro de que te sentirás cómodo aquí.",
  ui_story_30780601_25_dialog_content = "Estoy seguro de que yo también, pero... ¿no te molestará esta distancia?",
  ui_story_30780601_26_dialog_content = "No te preocupes... No me molesta tanto en mi propia casa.",
  ui_story_30780601_27_dialog_content = "Además, nos conocemos desde hace mucho tiempo, PlayerName... No debería ser un problema.",
  ui_story_30780601_28_dialog_content = "Solo... Trata de no hacer movimientos bruscos.",
  ui_story_30780601_29_dialog_content = "De acuerdo, intentaré tener cuidado...",
  ui_story_30780601_30_dialog_content = "Entonces, ya voy.",
  ui_story_30780601_31_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30780601_32_dialog_content = "Es un poco pequeño... Toma asiento donde prefieras... Lamento no haber preparado nada de antemano...",
  ui_story_30780601_33_dialog_content = "Está bien. Puede que no haya mucho espacio aquí, pero se siente realmente acogedor.",
  ui_story_30780601_34_dialog_content = "Acogedor y cálido, e incluso...",
  ui_story_30780601_35_dialog_content = "¿Pasa algo?",
  ui_story_30780601_36_dialog_content = "No, pero tengo que decir... ¡Tu atuendo se ve realmente especial hoy, Robyn!",
  ui_story_30780601_37_dialog_content = "No suelo verte así...",
  ui_story_30780601_38_dialog_content = "...",
  ui_story_30780601_39_dialog_content = "... Sabía que no debería haberte dejado entrar. Si te molesta demasiado, siempre puedes irte.",
  ui_story_30780601_40_dialog_content = "¡E-Eso no es en absoluto! Quería decir que te queda sorprendentemente bien!",
  ui_story_30780601_41_dialog_content = "¡Es un soplo de aire fresco comparado con el atuendo todo negro que sueles llevar!",
  ui_story_30780601_42_dialog_content = "...",
  ui_story_30780601_43_dialog_content = "(Es realmente difícil saber qué está pensando Robyn en este momento...)",
  ui_story_30780601_44_dialog_content = "(Si tan solo bajara la guardia de vez en cuando... Solo espero que no me malinterprete.)",
  ui_story_30780601_45_dialog_content = "¿En serio? G-Gracias por el cumplido, PlayerName...",
  ui_story_30780601_46_dialog_content = "(Uf... Gracias a Dios que ella entendió.)",
  ui_story_30780601_47_dialog_content = "No interactúo con personas así muy a menudo, así que no tenía idea... qué tipo de impresión causaría...",
  ui_story_30780601_48_dialog_content = "Creo que te queda realmente bien.",
  ui_story_30780601_49_dialog_content = "Yo... Ya lo entiendo. No necesitas repetirte...",
  ui_story_30780601_50_dialog_content = "Voy a preparar un poco de té para nosotros... ¿Por qué no te sientas en la cama por ahora, PlayerName?",
  ui_story_30780601_51_dialog_content = "Uh, ¿realmente está bien que me siente allí?",
  ui_story_30780601_52_dialog_content = "La gente rara vez viene aquí, así que... nunca me molesté en comprar muebles para los invitados.",
  ui_story_30780601_53_dialog_content = "Así que por favor siéntate en la cama. Si Dayna estuviera aquí, incluso se tiraría sobre ella...",
  ui_story_30780601_54_dialog_content = "Eh... Bueno, si insistes.",
  ui_story_30780601_55_dialog_content = "Tu té está listo... Lo dejaré justo aquí.",
  ui_story_30780601_56_dialog_content = "Gracias. Tomaré un poco en un rato.",
  ui_story_30780601_57_dialog_content = "Voy a empezar a leer ahora. Si tengo problemas para entender algo—",
  ui_story_30780601_58_dialog_content = "Me lo explicarás, ¿verdad?",
  ui_story_30780601_59_dialog_content = "Claro. Mientras tanto, buscaré algo más para leer.",
  ui_story_30780601_60_dialog_content = "Está bien...",
  ui_story_30780601_61_dialog_content = "...",
  ui_story_30780601_62_dialog_content = "(Es tan tranquilo... El único ruido es el sonido de las páginas pasando.)",
  ui_story_30780601_63_dialog_content = "(Así es como se ve Robyn cuando está perdida en su lectura...)",
  ui_story_30780601_64_dialog_content = "(Su cama es tan suave, y el sol de la tarde se siente realmente agradable...)",
  ui_story_30780601_65_dialog_content = "*bostezando*",
  ui_story_30780601_66_dialog_content = "¿Te sientes somnoliento, PlayerName?",
  ui_story_30780601_67_dialog_content = "Ah... No, estoy bien. Es solo que es realmente cómodo aquí.",
  ui_story_30780601_68_dialog_content = "De hecho... No creo que me haya sentido tan relajado en mucho tiempo.",
  ui_story_30780601_69_dialog_content = "Entonces... ¿Te gustaría tomar una siesta?",
  ui_story_30780601_70_dialog_content = "¿Ah?",
  ui_story_30780601_71_dialog_content = "No te preocupes... Acabo de lavar y secar la ropa de cama hoy...",
  ui_story_30780601_72_dialog_content = "¡Eso no es lo que me preocupa! ¡Tu cama está mucho más limpia que la mía, Robyn!",
  ui_story_30780601_73_dialog_content = "No solo eso... Hay un aroma suave y agradable que viene de las sábanas.",
  ui_story_30780601_74_dialog_content = "Bueno, sí utilicé un detergente nuevo y popular para lavarlos antes.",
  ui_story_30780601_75_dialog_content = "Dicen que se supone que el aroma tiene propiedades curativas, así que quería probarlo...",
  ui_story_30780601_76_dialog_content = "¿Cómo te sientes, PlayerName?",
  ui_story_30780601_77_option_content = "Se siente realmente cómodo.",
  ui_story_30780601_78_dialog_content = "El calor de tu habitación solo añade a la sensación también.",
  ui_story_30780601_79_dialog_content = "Es tan relajante aquí.",
  ui_story_30780601_80_dialog_content = "Tan relajante... que cada vez es más difícil mantenerse despierto...",
  ui_story_30780601_81_option_content = "Se siente realmente especial.",
  ui_story_30780601_82_dialog_content = "Los productos más populares de Umbraton siempre son tan únicos.",
  ui_story_30780601_83_dialog_content = "Es una combinación perfecta para tu habitación, Robyn.",
  ui_story_30780601_84_dialog_content = "Para ser honesto, solo estar aquí me hace sentir un poco mareado...",
  ui_story_30780601_85_dialog_content = "Ah... Realmente no es nada especial.",
  ui_story_30780601_86_dialog_content = "Compro cosas así de vez en cuando... Pero siempre me preocupo... de que se desperdiciarán.",
  ui_story_30780601_87_dialog_content = "Entonces... Gracias por compartir tus pensamientos conmigo, PlayerName.",
  ui_story_30780601_88_dialog_content = "Debes estar cansado después de viajar tan lejos solo para entregar algunos libros... ¿Verdad?",
  ui_story_30780601_89_dialog_content = "S-Si no te importa... Por favor... Siéntete libre de descansar un rato.",
  ui_story_30780601_90_dialog_content = "E-Está bien, entonces... Solo cerraré mis ojos un poco.",
  ui_story_30780601_91_dialog_content = "<color=#e8d9bb>Golpear-</color>",
  ui_story_30780601_92_dialog_content = "(Tan increíblemente cómodo...)",
  ui_story_30780601_93_dialog_content = "(Robyn todavía está leyendo... Parece una ratona de biblioteca en este momento...)",
  ui_story_30780601_94_dialog_content = "(Mis párpados... Están empezando a sentirse realmente pesados...)",
  ui_story_30780601_95_dialog_content = "<color=#e8d9bb>En el calor del sol de la tarde, una siesta corta puede fácilmente extenderse por horas...</color>",
  ui_story_30780601_96_dialog_content = "Zzzz... Zzzz... ¿Mmm?",
  ui_story_30780601_97_dialog_content = "(¡Oh no, me quedé dormido! ¿Cuánto tiempo estuve inconsciente?)",
  ui_story_30780601_98_dialog_content = "(Esto es malo, se supone que debo contarle a Robyn más sobre estos libros! Espero que no esté demasiado...)",
  ui_story_30780601_99_dialog_content = "Zzzz... Zzzz...",
  ui_story_30780601_100_dialog_content = "Ah... ¿Ella también está dormida?",
  ui_story_30780601_101_dialog_content = "El sol está un poco demasiado brillante ahora. Debería cerrar las cortinas de Robyn para ella.",
  ui_story_30780601_102_dialog_content = "Pero... Me preocupa que pueda despertarla.",
  ui_story_30780601_103_dialog_content = "Tendría que pasar por encima de ella y alcanzar su escritorio para cerrarlos.",
  ui_story_30780601_104_dialog_content = "No será fácil, ¡pero tengo que intentarlo!",
  ui_story_30780601_105_dialog_content = "Zzzz... ¿Mmm?",
  ui_story_30780601_106_dialog_content = "Ah, lo siento... ¿Te desperté?",
  ui_story_30780601_107_dialog_content = "Hmm... No... No realmente...",
  ui_story_30780601_108_dialog_content = "Yo... me desperté por mi cuenta.",
  ui_story_30780601_109_dialog_content = "Fue un sueño tan agradable también... Me seguía diciendo a mí mismo que no podía quedarme dormido para siempre...",
  ui_story_30780601_110_dialog_content = "¿En serio? ¿De qué se trataba, Robyn?",
  ui_story_30780601_111_dialog_content = "Soñé con el cielo y el mar, con montañas y bosques... y con nosotros. Soñé que volábamos a través de todo.",
  ui_story_30780601_112_dialog_content = "\"A nosotros\"?",
  ui_story_30780601_113_dialog_content = "Así es, PlayerName, tú y yo...",
  ui_story_30780601_114_dialog_content = "Estábamos flotando en la brisa como plumas... y a la deriva en las olas del océano...",
  ui_story_30780601_115_dialog_content = "Escuchando a las cigarras en el bosque... y corriendo a través de un estanque de lotos después de la lluvia...",
  ui_story_30780601_116_dialog_content = "Eso suena como un sueño maravilloso...",
  ui_story_30780601_117_dialog_content = "Estoy bastante seguro de que tenía algo que ver con el libro que estaba leyendo...",
  ui_story_30780601_118_dialog_content = "Hay algo verdaderamente mágico en la prosa y la poesía narrativa...",
  ui_story_30780601_119_dialog_content = "Incluso había algunos poemas de Longzhou... Aunque no pude entender completamente su significado, entendí lo suficiente para apreciar su arte.",
  ui_story_30780601_120_dialog_content = "¿Quieres leer algunos de ellos conmigo, PlayerName?",
  ui_story_30780601_121_dialog_content = "Uh... Seguro, pero no soy exactamente un experto en el asunto... Mis interpretaciones tampoco podrían ser muy precisas.",
  ui_story_30780601_122_dialog_content = "Si eso no es un problema para ti, entonces me encantaría leer algo de poesía contigo.",
  ui_story_30780601_123_dialog_content = "Para nada... Aquí, compartiré mi asiento contigo.",
  ui_story_30780601_124_dialog_content = "Está bien, ¿pero estás seguro de esto? Estaremos sentados muy cerca el uno del otro...",
  ui_story_30780601_125_dialog_content = "Estaré bien. Hace tanto calor...",
  ui_story_30780601_126_dialog_content = "¿Calor? Sí, el sol está bastante cálido hoy...",
  ui_story_30780601_127_dialog_content = "Jeje, seguro que sí...",
  ui_story_30780601_128_dialog_content = "Aquí... Este es el verso que estaba leyendo antes de quedarme dormido...",
  ui_story_30780601_129_dialog_content = "Veamos aquí...",
  ui_story_30780601_130_dialog_content = "\"Los vientos del sur conocen mi corazón y llevan mis sueños al oeste.\"",
  ui_story_30780601_131_dialog_content = "Entonces... ¿Qué significa?",
  ui_story_30780601_132_dialog_content = "Si tuviera que adivinar... El autor quiere visitar un lugar lejano en sus sueños y compartir sus sentimientos con alguien allí... ¿Quizás su ciudad natal?",
  ui_story_30780601_133_dialog_content = "Su ciudad natal... Mi ciudad natal...",
  ui_story_30780601_134_dialog_content = "¿Eh? ¿Qué pasa, Robyn?",
  ui_story_30780601_135_dialog_content = "No es nada... Entonces, ¿soñaste con algo, PlayerName?",
  ui_story_30780601_136_dialog_content = "Bueno... Me desperté tan de repente que realmente no puedo recordar nada.",
  ui_story_30780601_137_dialog_content = "Pero justo antes de quedarme dormido, te vi leyendo tranquilamente a la luz del sol. Fue una vista tan calmada y pacífica.",
  ui_story_30780601_138_dialog_content = "Estoy bastante seguro de que me transmitiste esa sensación de paz, ¡por eso dormí tan bien justo ahora!",
  ui_story_30780601_139_dialog_content = "Entiendo...",
  ui_story_30780601_140_dialog_content = "Aparte de Dayna, nunca me he sentido tan relajado con otra persona...",
