  ui_story_30780601_142_dialog_content = "No lo seas. Cuando estás aquí conmigo, siento que puedo concentrarme aún mejor en mi lectura.",
  ui_story_30780601_143_dialog_content = "En realidad... Hay otro tipo de libro que quiero leer contigo, PlayerName...",
  ui_story_30780601_144_dialog_content = "La poesía es agradable y todo, pero tiende a hacer que la gente se duerma... Los libros en los que estoy pensando están destinados a captar realmente la atención del lector, casi como por arte de magia.",
  ui_story_30780601_145_dialog_content = "¿Oh? Entonces, ¿qué tipo de libros son?",
